"""Build a download-first static site entirely from recorded evidence and real model pixels."""
import csv
import html
import json
import shutil
from pathlib import Path
import markdown
import numpy as np
import rasterio
from PIL import Image
from core import ROOT

DOCS=ROOT/'docs'
def load(p): return json.loads((ROOT/p).read_text())
def e(x): return html.escape(str(x))
def page(title,body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · GEMSDOE45</title><meta name="description" content="A unique, reproducible fault-prediction GeoTIFF, spatial validation, and an honest submission gate for the DOE GEMS Prize."><link rel="stylesheet" href="style.css"><script src="site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html">GEMS<span>45 / FIELD NOTES</span></a><nav aria-label="Main"><a href="index.html">Overview</a><a href="research.html">Research</a><a href="validation.html">Validation</a><a href="sources.html">Sources</a><a href="executive-summary.html">How to submit ↗</a></nav></header><main id="main">{body}</main><footer><span>GEMSDOE45 · Maximize P(Win). Own the Outcome.<br>Research evidence, not a promise of leaderboard performance.</span><span><a href="brief.html">Standing project brief</a> · <a href="review.html">Three-pass audit</a> · <a href="https://github.com/buffedlizard55-lab/GEMSDOE45">Code & reproduction ↗</a></span></footer></body></html>'''
def write(name,title,body): (DOCS/name).write_text(page(title,body))
def md(text): return '<article class="prose">'+markdown.markdown(text,extensions=['tables','fenced_code'])+'</article>'

def main():
    audit=load('docs/downloads/submission-audit.json'); hold=load('evidence/holdout.json'); official=load('evidence/official_sources.json'); inventory=load('evidence/prior_inventory.json'); fingerprints=load('evidence/prior_fingerprints.json')
    compared=[r for r in fingerprints['files'] if r['status']=='fingerprinted']
    identical=[r for r in compared if r['canonical_pixel_sha256']==audit['pixel_sha256']]
    if identical: raise ValueError('Candidate duplicates an inventoried prior raster')
    uniqueness=dict(candidate_pixel_sha256=audit['pixel_sha256'],compared=len(compared),different_grid_or_bands=sum(r['status']=='different_grid_or_bands' for r in fingerprints['files']),unavailable=sum(r['status']=='unavailable' for r in fingerprints['files']),identical_predictions=len(identical),scope=fingerprints['scope'],not_claimed='Exhaustive uniqueness across every historical release, inaccessible file or private artifact')
    (ROOT/'evidence/uniqueness.json').write_text(json.dumps(uniqueness,indent=2)+'\n')
    (DOCS/'data').mkdir(exist_ok=True)
    for path in (ROOT/'evidence').glob('*.json'): shutil.copyfile(path,DOCS/'data'/path.name)
    shutil.copyfile(ROOT/'research/score_claims.csv',DOCS/'data/score_claims.csv')
    filename=audit['file']; tif='downloads/'+filename; zipurl=tif.replace('.tif','.zip')
    with rasterio.open(DOCS/tif) as s:
        a=s.read(1); valid=s.read_masks(1)>0
    # Aggregate to 500 m display cells. An overview of the actual prediction, not a basemap.
    h,w=a.shape; hh=(h//5)*5; ww=(w//5)*5
    dots=a[:hh,:ww].reshape(hh//5,5,ww//5,5).max(axis=(1,3))>0
    footprint=valid[:hh,:ww].reshape(hh//5,5,ww//5,5).max(axis=(1,3))
    rgb=np.full((*dots.shape,3),[23,59,54],dtype=np.uint8); rgb[footprint]=[54,83,70]; rgb[dots]=[225,171,104]
    Image.fromarray(rgb).save(DOCS/'prediction-overview.png')
    table=''.join(f'<tr><td>0{r["fold"]+1}</td><td>{r["baseline"]["test"]["dti"]:.6f}</td><td>{r["phase"]["test"]["dti"]:.6f}</td><td class="good">{r["paired_delta"]:+.6f}</td><td>{r["test_truth"]:,}</td></tr>' for r in hold['folds'])
    foldtable=f'<div class="table-wrap"><table><thead><tr><th>Quadrant</th><th>Baseline DTI</th><th>Phase DTI</th><th>Paired Δ</th><th>Truth pixels</th></tr></thead><tbody>{table}</tbody></table></div>'
    write('index.html','Fault discovery, with evidence',f'''
<div class="eyebrow">DOE GEMS Prize / Experiment H45-PHASE / 06 October 2026</div>
<section class="hero"><div><h1>A different signal.<br>A testable hypothesis.</h1><p class="intro">A new fault detector using differential phase parity across topography, magnetics and gravity. Original predictions. Measured validation. One downloadable GeoTIFF.</p><span class="pill">RESEARCH DOWNLOAD · SUBMISSION GATE CLOSED</span><div class="actions"><a class="button" href="{tif}" download>↓ Download unique TIF <span>348 KiB</span></a><a class="button secondary" href="{zipurl}" download>ZIP ↗</a></div><div class="file">{e(filename)}</div><p class="small">Single-band float32 · EPSG:32611 · 100 m · all stored values in [0,1]</p><div class="notice"><strong>Do not spend a weekly slot yet.</strong> The local spatial proxy passes. Independent off-catalogue confirmation and a comparable incumbent holdout are still missing. Portal acceptance is untested.</div><a href="executive-summary.html">Submission name, note & instructions →</a></div><figure class="map"><span class="label">PREDICTION FOOTPRINT / UTM 11N · N ↑</span><img src="prediction-overview.png" alt="Actual H45 predicted fault pixels in amber within the GeoDAWN footprint. Overview aggregated to 500 metre display cells."><figcaption><span>● Amber: predicted cells, not verified faults</span><span>500 m display aggregation</span></figcaption></figure></section>
<div class="metrics"><div class="metric"><span>New predicted pixels</span><strong>{audit['positive_pixels']:,}</strong></div><div class="metric"><span>Paired holdout improvement</span><strong>+{hold['mean_delta']:.4f}</strong></div><div class="metric"><span>Quadrants improved</span><strong>4 / 4</strong></div><div class="metric"><span>Prior rasters compared</span><strong>{len(compared)}</strong></div></div>
<section class="section two-col"><div><div class="eyebrow">01 / What changed</div><h2>A new detector.<br>Not another renamed file.</h2><p>Earlier leading artifacts improved the economics of the distance-weighted metric by thinning dots and pruning catalogue flanks. This experiment changes what is detected: step-like boundaries versus symmetric ridges, at two spatial scales.</p><a href="research.html">Read the scientific argument →</a></div><div><h3>Novel predictions, bounded claims</h3><p>The model was trained from supplied features. No previous submission was blended into it. Its pixels differ from all {len(compared)} comparable prior raster blobs checked; {uniqueness['different_grid_or_bands']} more had incompatible grids or bands.</p><p>This is an inventory-scoped audit, not proof about unavailable historical artifacts. Neither these predictions nor the 0.2085 local proxy score establish a new geothermal discovery.</p><a href="data/uniqueness.json">Inspect the uniqueness receipt ↗</a></div></section>
<section class="section"><div class="eyebrow">02 / The evidence</div><h2>One frozen experiment. Four geographic tests.</h2><p>Both arms use the same classifier, sampling and spacing. The candidate adds 15 bounded phase-parity descriptors to 31 baseline features. A separate quadrant selects the emission budget; 3 km split-line exclusions prevent nearby train/test contamination.</p>{foldtable}<p class="small">Mean baseline {hold['baseline_mean']:.6f} → candidate {hold['phase_mean']:.6f}. Catalogue-transfer proxy only. The 0.2778 incumbent was pruned away from these labels, so using it as a baseline here would manufacture a misleading win.</p><a href="validation.html">Protocol, raw results & limitations →</a></section>
<section class="section"><div class="eyebrow">03 / A usable research system</div><div class="cards"><article class="card"><span class="num">01 — REPRODUCE</span><h3>Data to download</h3><p>Checksum-pinned mirror restoration, CPU training, geographic validation and a fail-closed raster writer.</p><a href="https://github.com/buffedlizard55-lab/GEMSDOE45#reproduce-without-competition-credentials">Run the pipeline →</a></article><article class="card"><span class="num">02 — VERIFY</span><h3>Every claim has a class</h3><p>Official statements, measured results, reported scores and scientific hypotheses remain separate.</p><a href="sources.html">Open the evidence register →</a></article><article class="card"><span class="num">03 — DECIDE</span><h3>Protect the next slot</h3><p>A catalogue proxy win is a research signal, not permission to claim a winning submission.</p><a href="executive-summary.html">Read the submission gate →</a></article></div></section>
<section class="section"><div class="eyebrow">04 / Source freshness</div><h3>The leaderboard target has moved.</h3><p>The official 2026-10-06 research snapshot shows <strong>0.3345</strong>, not the prompt’s 0.3195. No organizer score exists for H45.</p><p id="feed-status" class="small">Dated research snapshot; checking the automated source-health feed…</p><a href="data/source_health.json">Source-health log ↗</a> · <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard ↗</a></section>''')
    instructions=f'''<div class="eyebrow">Executive summary / Submission guide</div><h1>The file is ready.<br>The slot is not approved.</h1><p class="intro">Download and inspect the original H45 artifact. Do not upload it to the competition until the missing validation gate is satisfied.</p><div class="actions"><a class="button" href="{tif}" download>↓ Download research TIF</a><a class="button secondary" href="{zipurl}" download>Single-TIF ZIP</a></div><div class="notice"><strong>Current decision: HOLD.</strong> Four catalogue-transfer folds improved. Independent off-catalogue confirmation and comparable incumbent validation are missing. Nothing has been uploaded; no weekly slot was used.</div><section class="section"><h2>Identify this experiment</h2><p><strong>Submission name</strong><br><code>{e(audit['unique_name'])}</code></p><p><strong>Optional note</strong></p><div class="note"><code id="submission-note">{e(audit['note'])}</code></div><button class="button secondary" data-copy-note>Copy note</button><p class="file">File SHA-256: {audit['sha256']}</p><a href="downloads/submission-audit.json">Independent re-read receipt →</a></section><section class="section prose"><h2>How submission works, once approved</h2><ol><li>Confirm the promotion gate has passed; verify the exact filename and hash. A local format pass alone is insufficient.</li><li>Download the <strong>.tif</strong>, or the ZIP containing just that TIFF. Do not upload this report, a JSON receipt, or a PNG overview.</li><li>Go to the <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">official competition</a>. Sign into your registered account and check eligibility and rules. This site cannot accept those legal commitments on your behalf.</li><li>Open <strong>New submission</strong>. Under <strong>File to submit</strong>, choose the downloaded TIFF or ZIP.</li><li>Paste the short note above in <strong>Note (optional)</strong>. The artifact’s unique filename also identifies the experiment.</li><li>Submit only if the slot is authorized. Record the organizer receipt, score and filename in the score register. Do not infer a score from a local test.</li><li>Before the deadline choose one final submission for both prize rounds. The rules state three submissions per week; check the current platform limits and deadline.</li></ol><h2>Why this file avoids invalid stored values</h2><p>Every stored cell is finite, between 0 and 1. There is no negative nodata sentinel. Cells outside the template footprint store zero and carry an internal invalid-data mask. The file has one float32 band, 3,730 rows × 3,292 columns, EPSG:32611, 100 m pixels and the template’s exact geotransform.</p><p>The published format describes null outside the bounds. Our internal mask preserves null-area semantics without storing NaNs. The platform’s actual mask handling is <strong>not verified</strong>; we cannot guarantee acceptance without an organizer receipt. We do not silently clip corrupt predictions to conceal a pipeline error.</p><h2>Reproduce, rather than trust a download</h2><pre>bash scripts/download_competition_data.sh\n.venv/bin/python scripts/prepare_data.py\n.venv/bin/python scripts/run_experiment.py\n.venv/bin/pytest -q\n.venv/bin/python scripts/verify_repo.py</pre><p>Install requirements first using the repository README. CPU is sufficient for this implementation. Mirrors are integrity-pinned but not organizer-authenticated.</p><h2>Finalist documentation</h2><p>Keep the code, exact input provenance, configuration, limitations and recorded results. The September 2026 rules require disclosure of generative AI use in the narrative. AI assisted this research, implementation and documentation; the raster is produced by numerical training and inference, not an image generator.</p><a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">Read all official rules ↗</a></section>'''
    write('executive-summary.html','Download & submission instructions',instructions)
    write('research.html','Scientific assessment',md((ROOT/'research/analysis.md').read_text()))
    write('hypotheses.html','Ranked hypotheses',md((ROOT/'research/hypotheses.md').read_text()))
    write('validation.html','Spatial validation',f'<div class="eyebrow">Validation / Frozen before evaluation</div><h1>A useful signal.<br>Not a leaderboard claim.</h1>{foldtable}<div class="notice">Local proxy gate: PASS. Competition-slot gate: CLOSED. Four folds are too few to justify a precise significance claim.</div><div class="actions"><a class="button secondary" href="data/holdout.json">Raw results JSON ↗</a><a class="button secondary" href="hypotheses.html">Frozen hypotheses & protocol ↗</a></div>'+md('''## What is held out?
Each quadrant is tested once. The next quadrant calibrates an emission fraction from {0.4%, 0.8%, 1.6%}; the other two fit the classifier. Train/calibration/test domains are at least 6 km apart across the center splits. No label-distance, coordinate, previous-prediction, or example-submission-value feature is used.

All four calibration rounds selected the largest candidate budget, 1.6%. This may indicate the search was budget-limited, but increasing the budget after seeing the test results would be a new experiment. Final training uses the median calibration-selected fraction, not an outer-test-selected setting.

## What remains unverified?
The missing-from-catalogue discovery target is not observable in these labels. There was no pre-existing holdout in the empty checkout. Comparing the catalogue-pruned H33 artifact against these same labels would be unfair. Therefore we cannot claim to have beaten the earlier group's true holdout best, or its 0.2778 organizer score.

The trained full-footprint artifact is not the out-of-fold prediction map. Full-data inference is allowed to learn from all provided public training labels. The reported holdout numbers come only from the separate fits described above.

## Format and uniqueness
The downloaded bytes are re-read independently. The format receipt checks grid, dtype, band count, finite range, outside-footprint values and mask. Our pixel identity comparison normalizes only the outside footprint: NaN versus zero packaging cannot masquerade as a unique prediction. Invalid in-footprint values are counted, not repaired in the prior audit.
''')+'<p><a href="data/prior_fingerprints.json">All prior pixel fingerprints ↗</a> · <a href="downloads/submission-audit.json">Format receipt ↗</a> · <a href="data/features.json">46 feature names and mirror metadata ↗</a></p>')
    rows=''.join(f'<tr><td><strong>{e(s["authority"])}</strong><br><a href="{e(s["url"])}">{e(s["id"])} ↗</a></td><td>{e(s["supports"])}</td><td>{e(s["status"])}</td></tr>' for s in official['sources'])
    priorrows=''.join(f'<tr><td>{e(r["repo"])}</td><td>{e(r["status"])}</td><td>'+ (f'<a href="{e(r["url"])}">Pinned source ↗</a>' if 'url' in r else e(r.get('error','')))+'</td></tr>' for r in inventory['repositories'])
    write('sources.html','Sources & provenance',f'<div class="eyebrow">Evidence register / Checked 06 October 2026</div><h1>Sources, not assurances.</h1><p>Official facts and accessible sources are listed below. Owner mirrors and user-reported scores are distinct evidence classes. Reading a source does not verify every downstream interpretation.</p><div class="table-wrap"><table><thead><tr><th>Authority / source</th><th>Supported claim</th><th>Review scope</th></tr></thead><tbody>{rows}</tbody></table></div><section class="section"><h2>Input data & irregularities</h2><p>The data came from SHA-256-pinned owner mirrors via GitHub API. Official data downloads require login. The sample mirror contains positive labels; only its geometry and finite mask are used. Ambiguous band metadata remain flagged rather than promoted to geological facts.</p><p><a href="data/data_receipt.json">Input checksum receipt</a> · <a href="research.html">Full irregularity register</a> · <a href="scores.html">All supplied historical score observations</a> · <a href="data/source_health.json">Automated reachability feed</a></p><p id="feed-status" class="small">Dated research snapshot; checking the automated source-health feed…</p></section><section class="section"><h2>Prior-site review scope</h2><p>Landing sources from 44 resolved repositories were inspected. GEMSDOE43 and GEMSDOE44 only had README titles. These are not exhaustive line-by-line source-code audits. The three reversed aliases failed; resolved names follow below.</p><div class="table-wrap"><table><thead><tr><th>Repository</th><th>Result</th><th>Manual review</th></tr></thead><tbody>{priorrows}</tbody></table></div></section>')
    scores=list(csv.DictReader((ROOT/'research/score_claims.csv').open()))
    score_rows=''.join(f'<tr><td>{e(r["repo"])}</td><td><code>{e(r["artifact"]) or "Not supplied"}</code></td><td>{e(r["reported_dti"]) or "Not supplied"}</td><td>{e(r["evidence_class"])}</td></tr>' for r in scores)
    write('scores.html','Historical score observations',f'<div class="eyebrow">Historical results / User supplied</div><h1>Scores are observations.<br>Not ground truth.</h1><p>These filename-to-score mappings reproduce the prompt, not independently authenticated organizer receipts. Blank results remain unknown. The public leaderboard does not expose the full per-file history.</p><p><a href="data/score_claims.csv" download>Download all observations as CSV ↓</a></p><div class="table-wrap"><table><thead><tr><th>Site</th><th>Artifact</th><th>Reported DTI</th><th>Evidence</th></tr></thead><tbody>{score_rows}</tbody></table></div>')
    brief=(ROOT/'README.md').read_text().split('# Standing project prompt',1)[1]
    write('brief.html','Standing project prompt',md('# Standing project prompt'+brief))
    review=ROOT/'research/review.md'
    if review.exists(): write('review.html','Three-pass review',md(review.read_text()))
    (DOCS/'.nojekyll').write_text('')
    print('Built site. Unique vs',len(compared),'compatible prior rasters.')
if __name__=='__main__': main()
